#pragma once

#include <WebServer.h>

// Embedded web UI (docs/web-ui.md section 5) and captive portal. Assets are
// the gzipped files generated by tools/build-web.mjs into web/web_assets.h;
// they ship inside the firmware image, so the UI works without an SD card.

namespace acorn {
namespace WebUi {

size_t assetCount();

// Serves a non-API request: an embedded asset (gzip, ETag, 304), a captive
// portal redirect, or a 404. Returns false if the request is not a GET.
bool serve(WebServer& server);

}  // namespace WebUi
}  // namespace acorn
